const rawQuery =
  typeof query === "string"
    ? query
    : query?.query;

const text = String(rawQuery ?? "").toLowerCase().trim();

let incident_type = "general_stress";
let incident_severity = "low";
let perpetrator_relationship = "unknown";
let repeated_incident = false;
let current_threat = false;
let social_support = "unknown";
let access_to_help = "unknown";

// =====================================================
// 1. INCIDENT TYPE
// =====================================================

const discriminationIndicators = [
  "discrimination",
  "discriminated",
  "caste discrimination",
  "caste",
  "untouchability",
  "social boycott",
  "excluded because of caste"
];

const violenceIndicators = [
  "violence",
  "violent",
  "assault",
  "attacked me",
  "attack me",
  "beaten",
  "beating me",
  "physical abuse",
  "physically abused"
];

const harassmentIndicators = [
  "harassment",
  "harassing me",
  "sexual harassment",
  "stalking",
  "stalking me"
];

const threatIndicators = [
  "threat",
  "threatened",
  "threatening",
  "intimidation",
  "intimidating",
  "blackmail",
  "blackmailing",
  "warned me",
  "said they would hurt me",
  "said he would hurt me",
  "said she would hurt me"
];

// Domestic ONLY when there is a relationship + abuse/harm context
const relationshipMentioned =
  text.includes("husband") ||
  text.includes("wife") ||
  text.includes("spouse") ||
  text.includes("partner") ||
  text.includes("boyfriend") ||
  text.includes("girlfriend");

const domesticHarmContext =
  text.includes("abuse") ||
  text.includes("abusing") ||
  text.includes("abused me") ||
  text.includes("beat me") ||
  text.includes("beats me") ||
  text.includes("hit me") ||
  text.includes("hits me") ||
  text.includes("hurt me") ||
  text.includes("threat") ||
  text.includes("threatened") ||
  text.includes("forcing me") ||
  text.includes("forced me") ||
  text.includes("controls me") ||
  text.includes("controlling me");

// Priority
if (discriminationIndicators.some(p => text.includes(p))) {
  incident_type = "discrimination";
} else if (violenceIndicators.some(p => text.includes(p))) {
  incident_type = "violence";
} else if (harassmentIndicators.some(p => text.includes(p))) {
  incident_type = "harassment";
} else if (threatIndicators.some(p => text.includes(p))) {
  incident_type = "threat";
} else if (relationshipMentioned && domesticHarmContext) {
  incident_type = "domestic";
} else {
  incident_type = "general_stress";
}

// =====================================================
// 2. PERPETRATOR RELATIONSHIP
// =====================================================

if (relationshipMentioned) {
  perpetrator_relationship = "partner";
} else if (
  text.includes("father") ||
  text.includes("mother") ||
  text.includes("brother") ||
  text.includes("sister") ||
  text.includes("family member")
) {
  perpetrator_relationship = "family";
} else if (
  text.includes("friend") &&
  (
    text.includes("threatened") ||
    text.includes("threatening") ||
    text.includes("hurt me")
  )
) {
  perpetrator_relationship = "friend";
} else if (
  text.includes("stranger") ||
  text.includes("unknown person")
) {
  perpetrator_relationship = "stranger";
}

// =====================================================
// 3. REPEATED INCIDENT
// IMPORTANT:
// Duration phrases such as "for the past few weeks"
// must NOT automatically mean repeated incidents.
// =====================================================

const repeatedIncidentIndicators = [
  "repeatedly threatened",
  "threatened me repeatedly",
  "threatened me several times",
  "threatened me many times",
  "threatened me multiple times",
  "hurt me repeatedly",
  "attacked me repeatedly",
  "abused me repeatedly",
  "harassed me repeatedly",
  "stalked me repeatedly",
  "again and again",
  "over and over",
  "several incidents",
  "multiple incidents",
  "many incidents",
  "this has happened several times",
  "this has happened many times",
  "this keeps happening",
  "keeps happening"
];

repeated_incident =
  repeatedIncidentIndicators.some(p => text.includes(p));

// =====================================================
// 4. CURRENT THREAT
// IMPORTANT:
// "right now" or "currently" ALONE is NOT a threat.
// We require a threat/danger signal too.
// =====================================================

const activeDangerIndicators = [
  "immediate danger",
  "in immediate danger",
  "danger right now",
  "in danger right now",
  "they are here",
  "he is here",
  "she is here",
  "they may hurt me",
  "he may hurt me",
  "she may hurt me",
  "going to hurt me",
  "about to hurt me",
  "attacking me",
  "trying to hurt me",
  "trying to kill me",
  "going to kill me"
];

const activeThreatIndicators = [
  "threatening me right now",
  "threatening me currently",
  "still threatening me",
  "ongoing threat",
  "ongoing danger",
  "threat is ongoing",
  "they are threatening me",
  "he is threatening me",
  "she is threatening me"
];

current_threat =
  activeDangerIndicators.some(p => text.includes(p)) ||
  activeThreatIndicators.some(p => text.includes(p));

// Explicit safety statement overrides generic "right now"
const explicitlySafe =
  text.includes("i am safe") ||
  text.includes("i'm safe") ||
  text.includes("safe right now") ||
  text.includes("currently safe") ||
  text.includes("i feel safe") ||
  text.includes("i feel safe right now");

if (explicitlySafe && !activeDangerIndicators.some(p => text.includes(p))) {
  current_threat = false;
}

// =====================================================
// 5. SOCIAL SUPPORT
// =====================================================

if (
  text.includes("good support") ||
  text.includes("strong support") ||
  text.includes("supportive family") ||
  text.includes("supportive friend") ||
  text.includes("someone i can talk to") ||
  text.includes("people i can talk to") ||
  text.includes("friends i can talk to") ||
  text.includes("my family supports me") ||
  text.includes("have support from my family")
) {
  social_support = "good";
} else if (
  text.includes("little support") ||
  text.includes("limited support") ||
  text.includes("not much support") ||
  text.includes("few people to help")
) {
  social_support = "moderate";
} else if (
  text.includes("no support") ||
  text.includes("no one to help") ||
  text.includes("nobody to help") ||
  text.includes("no one nearby") ||
  text.includes("i am alone") ||
  text.includes("i'm alone") ||
  text.includes("no support around me")
) {
  social_support = "low";
}

// =====================================================
// 6. ACCESS TO HELP
// =====================================================

if (
  text.includes("cannot get help") ||
  text.includes("can't get help") ||
  text.includes("no one can help") ||
  text.includes("cannot report") ||
  text.includes("can't report") ||
  text.includes("no access to help")
) {
  access_to_help = "low";
} else if (
  text.includes("can get help") ||
  text.includes("can contact") ||
  text.includes("can report") ||
  text.includes("have someone to help") ||
  text.includes("have access to help")
) {
  access_to_help = "good";
} else if (
  text.includes("difficult to get help") ||
  text.includes("hard to get help")
) {
  access_to_help = "moderate";
}

// =====================================================
// 7. INCIDENT SEVERITY
// =====================================================

if (
  text.includes("immediate danger") ||
  text.includes("in immediate danger") ||
  text.includes("danger right now") ||
  text.includes("in danger right now") ||
  text.includes("about to hurt me") ||
  text.includes("attacking me right now") ||
  text.includes("trying to kill me right now") ||
  text.includes("going to kill me right now")
) {
  incident_severity = "critical";
} else if (
  text.includes("threatened me") ||
  text.includes("threatening me") ||
  text.includes("threat") ||
  text.includes("assault") ||
  text.includes("violence") ||
  text.includes("beaten") ||
  text.includes("beating me") ||
  text.includes("very afraid") ||
  text.includes("very scared") ||
  text.includes("terrified") ||
  text.includes("afraid to go home") ||
  text.includes("scared to go home")
) {
  incident_severity = "high";
} else if (
  text.includes("very stressed") ||
  text.includes("very anxious") ||
  text.includes("overwhelmed") ||
  text.includes("unable to cope") ||
  text.includes("difficult to cope")
) {
  incident_severity = "moderate";
} else if (
  text.includes("stress") ||
  text.includes("stressed") ||
  text.includes("worried") ||
  text.includes("anxious") ||
  text.includes("uneasy") ||
  text.includes("concerned")
) {
  incident_severity = "low";
}

// =====================================================
// 8. SAFETY CONSISTENCY
// =====================================================

if (
  current_threat &&
  incident_severity === "low"
) {
  incident_severity = "high";
}

if (
  incident_type === "general_stress" &&
  explicitlySafe &&
  !current_threat &&
  !repeated_incident
) {
  incident_severity =
    text.includes("very anxious") ||
    text.includes("very stressed") ||
    text.includes("overwhelmed") ||
    text.includes("difficult to cope")
      ? "moderate"
      : "low";
}

// =====================================================
// 9. RETURN
// =====================================================

return JSON.stringify({
  incident_type,
  incident_severity,
  perpetrator_relationship,
  repeated_incident,
  current_threat,
  social_support,
  access_to_help
});

