// 3 = high
// 4 = critical
// ============================================================

let distress = 0;
let threat = 0;
let immediateDanger = 0;
let socialVulnerability = 0;
let incidentSeverity = 0;
let selfHarm = 0;
let historicalRisk = 0;
let supportGap = 0;

// ============================================================
// 1. DISTRESS
// ============================================================

if (
  hasAny([
    "terrified",
    "extremely afraid",
    "extremely scared",
    "panic attack",
    "panicking",
    "cannot breathe",
    "can't breathe"
  ])
) {
  distress = 4;
} else if (
  hasAny([
    "very afraid",
    "very scared",
    "extremely worried",
    "overwhelmed",
    "cannot cope",
    "can't cope",
    "unable to cope"
  ])
) {
  distress = 3;
} else if (
  hasAny([
    "stressed",
    "stress",
    "worried",
    "anxious",
    "anxiety",
    "fear",
    "afraid",
    "scared",
    "upset"
  ])
) {
  distress = 2;
} else if (
  hasAny([
    "concerned",
    "uneasy",
    "nervous"
  ])
) {
  distress = 1;
}

// ============================================================
// 2. THREAT
// ============================================================

if (
  hasAny([
    "threatened me",
    "threatening me",
    "threatened to kill me",
    "threatened to hurt me",
    "kill me",
    "going to kill me",
    "going to hurt me",
    "about to hurt me",
    "trying to hurt me",
    "attacking me",
    "attacked me"
  ])
) {
  threat = 4;
} else if (
  hasAny([
    "threat",
    "threats",
    "intimidating me",
    "intimidation",
    "being intimidated",
    "coercion",
    "being coerced"
  ])
) {
  threat = 3;
}

// ============================================================
// 3. IMMEDIATE DANGER
// ============================================================

// IMPORTANT:
// "right now" alone is NOT enough.
// We require a danger indicator AND we make sure the person
// did not explicitly state that they are safe.

const dangerSignal = hasAny([
  "immediate danger",
  "danger right now",
  "in danger right now",
  "they are here",
  "he is here",
  "she is here",
  "they're here",
  "he's here",
  "she's here",
  "going to hurt me",
  "about to hurt me",
  "attacking me",
  "attacking us",
  "trying to hurt me",
  "trying to kill me"
]);

if (!explicitlySafe && dangerSignal) {
  immediateDanger = 4;
}

// ============================================================
// 4. SOCIAL VULNERABILITY
// ============================================================

if (
  hasAny([
    "completely alone",
    "totally alone",
    "no support",
    "no one nearby",
    "nobody nearby",
    "no one can help",
    "nobody can help",
    "i have no one",
    "i don't have anyone",
    "i do not have anyone"
  ])
) {
  socialVulnerability = 4;
} else if (
  hasAny([
    "alone",
    "few people",
    "little support",
    "limited support"
  ])
) {
  socialVulnerability = 3;
}

// Positive support should not increase vulnerability.
if (
  hasAny([
    "good support",
    "strong support",
    "family support",
    "friends support",
    "friend i can talk to",
    "people i can talk to",
    "someone i can talk to",
    "someone can help me"
  ])
) {
  socialVulnerability = 0;
}

// ============================================================
// 5. INCIDENT SEVERITY
// ============================================================

if (
  hasAny([
    "immediate danger",
    "serious violence",
    "severe violence",
    "attacking me",
    "attacked me",
    "trying to kill me",
    "going to kill me",
    "kill me"
  ])
) {
  incidentSeverity = 4;
} else if (
  hasAny([
    "threatened me",
    "threatening me",
    "threat",
    "threats",
    "violence",
    "violent",
    "assault",
    "assaulted",
    "intimidation"
  ])
) {
  incidentSeverity = 3;
} else if (
  hasAny([
    "harassment",
    "discrimination",
    "domestic issue",
    "stress",
    "anxiety",
    "anxious",
    "worried"
  ])
) {
  incidentSeverity = 2;
} else if (
  hasAny([
    "concerned",
    "uneasy",
    "minor issue"
  ])
) {
  incidentSeverity = 1;
}

// ============================================================
// 6. SELF-HARM
// ============================================================

if (
  hasAny([
    "kill myself",
    "hurt myself",
    "harm myself",
    "self harm",
    "self-harm",
    "suicide",
    "suicidal",
    "want to die",
    "end my life",
    "take my own life"
  ])
) {
  selfHarm = 4;
}

// ============================================================
// 7. HISTORICAL / REPEATED RISK
// ============================================================

if (
  hasAny([
    "many times",
    "several times",
    "repeatedly",
    "again and again",
    "over and over",
    "multiple times",
    "keeps happening",
    "kept happening"
  ])
) {
  historicalRisk = 3;
} else if (
  hasAny([
    "again",
    "before",
    "in the past",
    "previously"
  ])
) {
  historicalRisk = 2;
}

// NOTE:
// "for the past few weeks/months" is NOT automatically treated
// as repeated violence because duration alone does not prove
// repeated incidents.

// ============================================================
// 8. SUPPORT GAP
// ============================================================

if (
  hasAny([
    "no one can help",
    "nobody can help",
    "cannot get help",
    "can't get help",
    "unable to get help",
    "no support",
    "no one nearby",
    "nobody nearby",
    "cannot report",
    "can't report",
    "afraid to report"
  ])
) {
  supportGap = 4;
} else if (
  hasAny([
    "little support",
    "limited support",
    "difficult to get help",
    "hard to get help"
  ])
) {
  supportGap = 3;
}

// Positive support lowers this component.
if (
  hasAny([
    "good support",
    "strong support",
    "family support",
    "friend can help",
    "friends can help",
    "someone can help me"
  ])
) {
  supportGap = 0;
}

// ============================================================
// BASE SVI CALCULATION
//
// Prototype weights:
// distress             20%
// threat               20%
// immediate danger     15%
// social vulnerability 10%
// incident severity    10%
// self-harm            15%
// historical risk       5%
// support gap           5%
// ============================================================

let score =
  (distress / 4) * 20 +
  (threat / 4) * 20 +
  (immediateDanger / 4) * 15 +
  (socialVulnerability / 4) * 10 +
  (incidentSeverity / 4) * 10 +
  (selfHarm / 4) * 15 +
  (historicalRisk / 4) * 5 +
  (supportGap / 4) * 5;

// ============================================================
// ESCALATION FLOORS
//
// These are prototype engineering rules.
// They make strong combinations visible to the responder.
//
// IMPORTANT:
// These do NOT diagnose anything.
// ============================================================

// Clear immediate danger
if (immediateDanger >= 4) {
  score = Math.max(score, 80);
}

// Self-harm indication
if (selfHarm >= 4) {
  score = Math.max(score, 80);
}

// Repeated threat + severe fear + unsafe situation
if (
  threat >= 3 &&
  distress >= 3 &&
  historicalRisk >= 3 &&
  !explicitlySafe
) {
  score = Math.max(score, 60);
}

// Threat + feeling unsafe
if (
  threat >= 3 &&
  hasAny([
    "don't feel safe",
    "do not feel safe",
    "i don't feel safe",
    "i do not feel safe",
    "feel unsafe",
    "afraid to go home",
    "not safe going home"
  ])
) {
  score = Math.max(score, 55);
}

// ============================================================
// FINAL SCORE
// ============================================================

const svi = Math.min(100, Math.max(0, Math.round(score)));

// ============================================================
// RISK LEVEL
// ============================================================

let risk_level = "LOW";

if (svi >= 75) {
  risk_level = "CRITICAL";
} else if (svi >= 50) {
  risk_level = "HIGH";
} else if (svi >= 25) {
  risk_level = "MODERATE";
}

// Safety overrides
if (immediateDanger >= 4 || selfHarm >= 4) {
  risk_level = "CRITICAL";
}

// ============================================================
// RETURN
// ============================================================

return JSON.stringify({
  svi,
  risk_level,

  components: {
    distress,
    threat,
    immediate_danger: immediateDanger,
    social_vulnerability: socialVulnerability,
    incident_severity: incidentSeverity,
    self_harm: selfHarm,
    historical_risk: historicalRisk,
    support_gap: supportGap
  }
});

// ============================================================
// SAHAY-V — TEMPORAL VULNERABILITY TRACKER
// Prototype only: tracks SVI changes for the current case.
// Does NOT diagnose or make autonomous decisions.
// ============================================================

// Get current assessment
const current = $input.first().json;

// ------------------------------------------------------------
// CURRENT VALUES
// ------------------------------------------------------------

const caseId = String(current.case_id ?? "");
const currentSvi = Number(current.svi ?? 0);
const currentRisk = String(current.risk_level ?? "UNKNOWN");

// ------------------------------------------------------------
// TEMPORAL MEMORY
// ------------------------------------------------------------
// Prototype storage using workflow static data.
// This allows repeated interactions for the same case
// to build a simple vulnerability trajectory.
// ------------------------------------------------------------

const staticData = $getWorkflowStaticData("global");

if (!staticData.temporalCases) {
  staticData.temporalCases = {};
}

if (!staticData.temporalCases[caseId]) {
  staticData.temporalCases[caseId] = {
    assessments: []
  };
}

const caseHistory = staticData.temporalCases[caseId];

// ------------------------------------------------------------
// PREVIOUS ASSESSMENT
// ------------------------------------------------------------

const previousAssessment =
  caseHistory.assessments.length > 0
    ? caseHistory.assessments[caseHistory.assessments.length - 1]
    : null;

const previousSvi = previousAssessment
  ? Number(previousAssessment.svi)
  : null;

const previousRisk = previousAssessment
  ? String(previousAssessment.risk_level)
  : null;

// ------------------------------------------------------------
// CALCULATE CHANGE
// ------------------------------------------------------------

let change = 0;

if (previousSvi !== null) {
  change = currentSvi - previousSvi;
}

// ------------------------------------------------------------
// DETERMINE TRAJECTORY
// ------------------------------------------------------------

let trajectory = "STABLE";

if (previousSvi === null) {
  trajectory = "INITIAL";
} else if (change >= 15) {
  trajectory = "ESCALATING";
} else if (change <= -15) {
  trajectory = "IMPROVING";
} else {
  trajectory = "STABLE";
}

// ------------------------------------------------------------
// RISK TRANSITION
// ------------------------------------------------------------

let riskTransition = "UNCHANGED";

if (previousRisk !== null && previousRisk !== currentRisk) {
  riskTransition = `${previousRisk} → ${currentRisk}`;
}

// ------------------------------------------------------------
// STORE CURRENT ASSESSMENT
// ------------------------------------------------------------

caseHistory.assessments.push({
  svi: currentSvi,
  risk_level: currentRisk,
  timestamp: new Date().toISOString()
});

// Keep only the latest 20 assessments for prototype use
if (caseHistory.assessments.length > 20) {
  caseHistory.assessments =
    caseHistory.assessments.slice(-20);
}

// ------------------------------------------------------------
// BUILD TEMPORAL HISTORY
// ------------------------------------------------------------

const sviHistory = caseHistory.assessments.map((item, index) => ({
  interaction_number: index + 1,
  svi: item.svi,
  risk_level: item.risk_level,
  timestamp: item.timestamp
}));

// ------------------------------------------------------------
// FINAL OUTPUT
// ------------------------------------------------------------

return {
  json: {
    ...current,

    temporal_tracking: {
      previous_svi: previousSvi,
      current_svi: currentSvi,
      change,
      trajectory,
      previous_risk_level: previousRisk,
      current_risk_level: currentRisk,
      risk_transition: riskTransition,
      assessment_count: caseHistory.assessments.length,
      svi_history: sviHistory
    }
  }
};
